export function cityUI({getActive,regenerate,scenes,fit}){
 let panel=document.querySelector('#city-panel');if(panel)return;
 panel=document.createElement('aside');panel.id='city-panel';panel.setAttribute('aria-label','City simulation');panel.innerHTML='<div class="city-actions"><button id="city-scenes">Scenes</button><button id="city-fit">Fit</button><button id="city-close" aria-label="Close city controls">×</button></div><label>Density <select id="city-density"><option value="1">Neighborhood</option><option value="2">Busy district</option><option value="3">Metropolis</option></select></label><p id="city-ledger"></p><p id="city-population"></p><details><summary>What is simulated?</summary><p>Couriers carry finite parcel stock from the depot to reachable building frontages. Residents walk between destinations. Traffic follows ambient circuits; passenger transport and a city economy are not simulated.</p></details><div id="city-activity"></div>';
 document.body.append(panel);document.querySelector('#city-scenes').onclick=scenes;document.querySelector('#city-fit').onclick=fit;document.querySelector('#city-close').onclick=()=>panel.classList.remove('city-open');document.querySelector('#city-density').onchange=e=>regenerate(+e.target.value);
 const toggle=document.createElement('button');toggle.id='city-controls';toggle.textContent='City';toggle.setAttribute('aria-label','City controls');toggle.onclick=()=>panel.classList.toggle('city-open');(document.querySelector('#toolbar-tools')||document.querySelector('header')).append(toggle);
 const style=document.createElement('style');style.textContent=`#city-panel,#city-controls{display:none}body[data-family=city] #city-controls{display:inline-flex}body[data-family=city] #city-panel{display:block;position:fixed;right:14px;top:76px;width:230px;max-height:calc(100dvh - 100px);overflow:auto;z-index:35;padding:14px;border-radius:16px;background:var(--app-paper,#fff9ec);color:var(--app-ink,#433c2b);font:13px Manrope,sans-serif;box-sizing:border-box}#city-panel p{line-height:1.55}#city-panel label{display:flex;align-items:center;gap:8px;margin:16px 0}#city-panel select{font:inherit;min-height:36px;max-width:150px}#city-panel button{font:inherit;min-height:36px}.city-actions{display:flex;gap:7px}#city-close{display:none}#city-activity{margin-top:14px;font-size:12px;white-space:pre-line;line-height:1.8}body[data-family=city] #current-scene-type,body[data-family=city] #panel{display:none!important}@media(max-width:700px){body[data-family=city] #city-panel{display:none;top:auto;bottom:12px;left:10px;right:10px;width:auto;max-height:38dvh}body[data-family=city] #city-panel.city-open{display:block}#city-close{display:block;margin-left:auto}}`;
 document.head.append(style);
}
export function updateCityUI(active){const ledger=document.querySelector('#city-ledger');if(!ledger)return;ledger.textContent=active.life.readout;const s=active.life.summary();document.querySelector('#city-population').textContent=s.buildings+' buildings · '+s.residents+' residents and couriers';document.querySelector('#city-density').value=String(active.plan.complexity);document.querySelector('#city-activity').textContent=active.life.workers.slice(0,10).map(w=>w.body.userData.inspect.title+' · '+w.phase).join('\n');}
